 function roleSummary(){const box=$('roleSummary');if(!box)return;const inputs=[...document.querySelectorAll('[data-role]')],total=inputs.reduce((n,el)=>n+Number(el.value||0),0),mafia=Number(document.querySelector('[data-role="mafia"]')?.value||0),players=game.players.filter(p=>!p.moderator).length,ordinary=Math.max(0,players-total),valid=total<=players&&mafia<Math.max(2,players/2);box.className='settings-summary '+(valid?'valid':'invalid');box.innerHTML=`<strong>Сейчас в комнате: ${players}</strong><span>Задано ролей: ${total}; обычных мирных при старте: ${ordinary}.</span>${total>players?'<span>Уберите '+(total-players)+' лишних ролей.</span>':''}${mafia>=Math.max(2,players/2)?'<span>Мафии должно быть меньше половины игроков.</span>':''}`;}
