 function clock(){if(!$('phaseClock')||!game)return;w.MafiaSignals.observe(game);const n=Math.max(0,Math.ceil(((game.wake?.deadline||game.deadline)-Date.now())/1000)),text=game.phase==='finished'?'':game.paused?'Пауза':!game.deadline?'':n?Math.floor(n/60)+':'+String(n%60).padStart(2,'0'):game.settings.gameMode==='hosted'?'Ожидаем ведущего':'Обработка…';$('phaseClock').textContent=text;$('phaseClock').setAttribute('aria-label',n?'Осталось '+n+' секунд':text);if($('actionClock'))$('actionClock').textContent=text||'без таймера';if($('sleepGuardClock'))$('sleepGuardClock').textContent=text||'—';}
